const listFixedAssets = `-- name: ListFixedAssets :many
SELECT f.id, f.code, f.name, f.class_id, f.location_id, f.location_label, f.division_id, f.acquisition_source, f.acquisition_date, f.acquisition_cost_amount, f.salvage_amount, f.useful_life_months, f.depreciation_start_date, f.opening_accumulated_amount, f.opening_depreciated_months, f.accumulated_amount, f.payment_account_id, f.status, f.acquisition_journal_id, f.disposal_date, f.disposal_proceeds_amount, f.disposal_account_id, f.disposal_reason, f.disposal_journal_id, f.note, f.created_at, f.created_by, f.updated_at, f.updated_by, f.version, f.deleted_at, f.deleted_by, c.name AS class_name
FROM fixed_assets f
JOIN fixed_asset_classes c ON c.id = f.class_id
WHERE f.deleted_at IS NULL
  AND ($1::text IS NULL OR f.status = $1)
  AND ($2::uuid IS NULL OR f.class_id = $2)
  AND ($3::text IS NULL OR f.code ILIKE '%' || $3 || '%' OR f.name ILIKE '%' || $3 || '%'
       OR f.location_label ILIKE '%' || $3 || '%')
ORDER BY f.code
LIMIT $5 OFFSET $4
`

