const lockFixedAsset = `-- name: LockFixedAsset :one
SELECT version FROM fixed_assets WHERE id = $1 FOR UPDATE
`

func (q *Queries) LockFixedAsset(ctx context.Context, id uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, lockFixedAsset, id)
	var version int32
	err := row.Scan(&version)
	return version, err
}

const refreshDepreciationRunTotals = `-- name: RefreshDepreciationRunTotals :exec
UPDATE depreciation_runs r
SET asset_count = t.cnt, total_amount = t.total
FROM (SELECT count(*)::integer AS cnt, coalesce(sum(amount), 0)::numeric AS total
      FROM depreciation_lines WHERE depreciation_run_id = $1) t
WHERE r.id = $1
`

func (q *Queries) RefreshDepreciationRunTotals(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, refreshDepreciationRunTotals, id)
	return err
}

