const upsertDepreciationRun = `-- name: UpsertDepreciationRun :one
INSERT INTO depreciation_runs (fiscal_period_id, created_by, updated_by)
VALUES ($1, $2, $2)
ON CONFLICT (fiscal_period_id) DO UPDATE
SET run_count = depreciation_runs.run_count + 1, last_run_at = now(), updated_at = now(), updated_by = $2,
    version = depreciation_runs.version + 1
RETURNING id
`

type UpsertDepreciationRunParams struct {
	FiscalPeriodID uuid.UUID
	ActorID        uuid.UUID
}

func (q *Queries) UpsertDepreciationRun(ctx context.Context, arg UpsertDepreciationRunParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertDepreciationRun, arg.FiscalPeriodID, arg.ActorID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}
